/* Card container */
.card {
  background-color: #ffffff;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  border-radius: 8px;
  padding: 30px;
  max-width: 400px;
}

/* Heading */
.card h2 {
  color: #2c3e50;
  font-family: 'Georgia', serif;
  margin-top: 0;
}

/* Title text */
.title {
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #7f8c8d;
}

/* Bio paragraph */
.bio {
  line-height: 1.6;
  color: #555;
}

/* Contact button */
.btn {
  background-color: #3498db;
  color: white;
  padding: 10px 20px;
  text-decoration: none;
  display: inline-block;
  border-radius: 4px;
}
